// Small inline widgets for section 01 and the table-of-contents highlight.
// Hand-written (not generated by src/build.py). Colours come from the page's CSS variables.
(function () {
  "use strict";
  function parse(t) {
    const parts = t.split("_"), m = parts[0].length / 3;
    return { n: parts.length, m, r: parts.map(p => Array.from({ length: m }, (_, i) => p.slice(3 * i, 3 * i + 3))) };
  }
  const name = s => String.fromCharCode(65 + s);
  const $ = id => document.getElementById(id);
  const css = v => getComputedStyle(document.documentElement).getPropertyValue(v).trim();

  // ---------------------------------------------------------- widget 1: one step at a time
  if ($("w1")) {
    const W = parse("1RB1LB_1LA1RZ");
    const tapeEl = $("w1-tape"), rulesEl = $("w1-rules"), sayEl = $("w1-say"), cntEl = $("w1-count"), stepB = $("w1-step");
    let t, h, s, n, halted;
    const reset = () => {
      t = {}; h = 0; s = 0; n = 0; halted = false;
      sayEl.innerHTML = '<span class="n">0</span>모든 칸이 0이고, 헤드는 상태 A에서 시작해요. <b>한 걸음</b>을 눌러 보세요.';
      draw();
    };
    const draw = last => {
      const R = 6;
      let html = "";
      for (let x = h - R; x <= h + R; x++) html += `<span class="${t[x] ? "one" : ""} ${x === h ? "hd" : ""}">${t[x] || 0}</span>`;
      tapeEl.innerHTML = html + `<em class="badge" style="left:${(R + 0.5) / (2 * R + 1) * 100}%">${halted ? "멈춤" : "상태 " + name(s)}</em>`;
      let r = '<div class="h"></div><div class="h">0을 읽으면</div><div class="h">1을 읽으면</div>';
      for (let q = 0; q < W.n; q++) {
        r += `<div class="h">${name(q)}</div>`;
        for (let k = 0; k < W.m; k++) r += `<div class="${last && last[0] === q && last[1] === k ? "on" : ""}">${W.r[q][k]}</div>`;
      }
      rulesEl.innerHTML = r;
      cntEl.textContent = `${n}걸음`;
      stepB.disabled = halted;
    };
    stepB.onclick = () => {
      if (halted) return;
      const read = t[h] || 0, rule = W.r[s][read], from = s;
      const w = +rule[0], d = rule[1], ns = rule.charCodeAt(2) - 65;
      t[h] = w; h += d === "R" ? 1 : -1; n++;
      const stop = ns >= W.n;
      sayEl.innerHTML = `<span class="n">${n}</span>상태 <b>${name(from)}</b>에서 <b>${read}</b>을 읽었어요 → 규칙 <code>${rule}</code>: ${w}을 쓰고 ${d === "R" ? "오른쪽" : "왼쪽"}으로, ` +
        (stop ? "<b>멈춤!</b> 6걸음 만에 끝났어요." : `상태 <b>${name(ns)}</b>로.`);
      if (stop) halted = true; else s = ns;
      draw([from, read]);
    };
    $("w1-reset").onclick = reset;
    reset();
  }

  // ---------------------------------------------------------- widget 2: steps stacked into a picture
  if ($("w2")) {
    const MS = [["1RB1LB_1LA1RZ", 6], ["1RB1RZ_1LB0RC_1LC1LA", 21], ["1RB1LB_1LA0LC_1RZ1LD_1RD0RA", 107]];
    const cv = $("w2-cv"), ctx = cv.getContext("2d"), sel = $("w2-sel"), playB = $("w2-play"), cnt = $("w2-count");
    let M, rows, timer;
    const snap = () => ({ t: { ...M.t }, h: M.h });
    const stop = label => { clearInterval(timer); timer = null; playB.textContent = label; };
    const reset = () => {
      stop("▶ 재생");
      const [tm, total] = MS[+sel.value];
      $("w2-name").textContent = tm;
      M = { m: parse(tm), t: {}, h: 0, s: 0, n: 0, done: false, total };
      rows = [snap()];
      draw();
    };
    const step = () => {
      if (M.done) return;
      const read = M.t[M.h] || 0, rule = M.m.r[M.s][read];
      M.t[M.h] = +rule[0]; M.h += rule[1] === "R" ? 1 : -1; M.n++;
      const ns = rule.charCodeAt(2) - 65;
      if (ns >= M.m.n) M.done = true; else M.s = ns;
      rows.push(snap());
    };
    const draw = () => {
      let lo = 0, hi = 0;
      for (const r of rows) for (const k of [r.h, ...Object.keys(r.t).map(Number)]) { lo = Math.min(lo, k); hi = Math.max(hi, k); }
      const totalRows = M.total + 1, span = Math.max(hi - lo + 1, 8);
      const c = Math.max(1, Math.min(Math.floor(cv.width / span), Math.floor(cv.height / totalRows) * 2, 26));
      const rh = Math.max(1, Math.min(c, Math.floor(cv.height / totalRows)));
      const x0 = Math.floor((cv.width - span * c) / 2) - (lo - Math.floor((span - (hi - lo + 1)) / 2)) * c;
      ctx.fillStyle = css("--soft"); ctx.fillRect(0, 0, cv.width, cv.height);
      const one = css("--cell1"), acc = css("--accent"), gx = c > 4 ? 1 : 0, gy = rh > 4 ? 1 : 0;
      rows.forEach((r, y) => {
        ctx.fillStyle = one;
        for (const k in r.t) if (r.t[k]) ctx.fillRect(x0 + k * c, y * rh, c - gx, rh - gy);
        ctx.fillStyle = acc; ctx.fillRect(x0 + r.h * c, y * rh, c - gx, rh - gy);
      });
      cnt.textContent = M.done ? `${M.n}걸음 · 멈춤` : `${M.n}걸음`;
    };
    playB.onclick = () => {
      if (timer) return stop("▶ 재생");
      if (M.done) reset();
      playB.textContent = "❚❚ 정지";
      timer = setInterval(() => { step(); draw(); if (M.done) stop("▶ 다시"); }, M.total > 50 ? 40 : 220);
    };
    $("w2-reset").onclick = reset;
    sel.onchange = reset;
    window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", () => draw());
    reset();
  }

  // ---------------------------------------------------------- table of contents: mark the section in view
  const links = [...document.querySelectorAll(".toc a")];
  const targets = links.map(a => document.querySelector(a.getAttribute("href"))).filter(Boolean);
  const mark = () => {
    let cur = targets[0];
    for (const t of targets) if (t.getBoundingClientRect().top < window.innerHeight * 0.35) cur = t;
    links.forEach(a => a.classList.toggle("on", a.getAttribute("href") === "#" + cur.id));
  };
  if (targets.length) { window.addEventListener("scroll", mark, { passive: true }); mark(); }
})();
